 'use strict';
 const F=CoverageFixture,M=CoverageStudyModel,study=new M.Study(F),original=structuredClone(F.blocks),$=s=>document.querySelector(s),labels={clear:'Clearly represented',partial:'Partly represented',not_represented:'Not represented in this CV',needs_review:'Needs review'},short={clear:'Clear',partial:'Partial',not_represented:'Not in this CV',needs_review:'Review'};
