 function openAd(signalId){const dialog=$('#ad-dialog'),text=$('#ad-text');text.replaceChildren();const selected=study.input.signals.find(s=>s.id===signalId);for(const paragraph of study.input.jobText.split('\n\n')){const p=el('p');if(selected?.adEvidence.quote===paragraph)p.append(el('mark',paragraph));else p.textContent=paragraph;text.append(p);}dialog.showModal();requestAnimationFrame(()=>text.querySelector('mark')?.scrollIntoView({block:'center'}));}
