 const mockClient=new DraftedDiscoveryClient.Client({endpoint:'/local-study-interpret',background:true,fetch:async(_url,options)=>{const r=JSON.parse(options.body);await new Promise(done=>setTimeout(done,220));return new Response(JSON.stringify({ok:true,schemaVersion:'1.0',operation:'interpret',requestId:r.requestId,contextRevision:r.contextRevision,result:{roundId:r.roundId,questionId:r.questionId,answerId:r.sourceAnswer.id,answerRevision:r.sourceAnswer.revision,drafts:[{proposedText:r.sourceAnswer.text,sourceQuote:r.sourceAnswer.text,coveredQuestionIds:[]}]}}),{headers:{'Content-Type':'application/json'}});}});
