  const body=el('div',undefined,'drafted-discovery');host.append(body);currentUI=DraftedExperienceDiscoveryUI.mount(body,session,{onAnswer:text=>mockClient.submit(session,text),onStateChange:()=>syncSource(session,id),onFinishAndTailor:async()=>{const key=M.binding(study.input);const status=el('p','Preparing your suggestion from the saved answer…','answer-saved');status.setAttribute('role','status');$('#review').replaceChildren(status);panel('review');await Promise.allSettled([...mockClient.inflight.values()]);if(key!==M.binding(study.input)){status.textContent='The CV or job description changed. Return to coverage and assess the current context.';return;}chooseContext(session,id);},onContinue:()=>{},onRetry:answerId=>mockClient.retry(session,answerId)});panel('conversation');
